// "Por qué paramos": renders the strategy explanation strings generated by the
// backend. The frontend only prints them.
export default function Explanation({ items }) {
  if (!items || !items.length) {
    return <p className="placeholder">Esperando datos para explicar la estrategia...</p>;
  }
  return (
    <>
      {items.map((i, idx) => (
        <div className={`expl ${i.tag}`} key={idx}>
          {i.text}
        </div>
      ))}
    </>
  );
}
